const searchQuestionsPage = `-- name: SearchQuestionsPage :many
WITH s AS (
  SELECT q.id, q.tayfa_id, q.author_id, q.title, q.body, q.created_at, q.updated_at,
         ts_rank(q.search_vector, websearch_to_tsquery('turkish'::regconfig, tr_lower($5::text)))::real AS rank
  FROM questions q
  WHERE q.tayfa_id = $6
    AND q.deleted_at IS NULL
    AND q.search_vector @@ websearch_to_tsquery('turkish'::regconfig, tr_lower($5::text))
    AND (NOT $7::boolean
         OR EXISTS (SELECT 1 FROM question_tags qt WHERE qt.question_id = q.id AND qt.tayfa_id = $6 AND qt.tag_id = $8::uuid))
)
SELECT s.id, s.tayfa_id, s.author_id, s.title, s.body, s.created_at, s.updated_at, s.rank,
       (SELECT count(*) FROM answers a WHERE a.question_id = s.id AND a.deleted_at IS NULL)::integer AS answer_count
FROM s
WHERE NOT $1::boolean
   OR (s.rank, s.id) < ($2::real, $3::uuid)
ORDER BY s.rank DESC, s.id DESC
LIMIT $4
`

type SearchQuestionsPageParams struct {
	HasCursor bool
	AfterRank float32
	AfterID   pgtype.UUID
	PageSize  int32
	Query     string
	TayfaID   pgtype.UUID
	HasTag    bool
	TagID     pgtype.UUID
}

type SearchQuestionsPageRow struct {
	ID          pgtype.UUID
	TayfaID     pgtype.UUID
	AuthorID    pgtype.UUID
	Title       string
	Body        string
	CreatedAt   pgtype.Timestamptz
	UpdatedAt   pgtype.Timestamptz
	Rank        float32
	AnswerCount int32
}

// Türkçe tam metin arama. Sorgu metni tr_lower ile, belgelerle aynı
// tabloya göre küçültülür; websearch_to_tsquery her girdiyi kabul eder.
// Sıra: ilgi azalan, eşitlikte yeniden eskiye.
func (q *Queries) SearchQuestionsPage(ctx context.Context, arg SearchQuestionsPageParams) ([]SearchQuestionsPageRow, error) {
	rows, err := q.db.Query(ctx, searchQuestionsPage,
		arg.HasCursor,
		arg.AfterRank,
		arg.AfterID,
		arg.PageSize,
		arg.Query,
		arg.TayfaID,
		arg.HasTag,
		arg.TagID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchQuestionsPageRow{}
	for rows.Next() {
		var i SearchQuestionsPageRow
		if err := rows.Scan(
			&i.ID,
			&i.TayfaID,
			&i.AuthorID,
			&i.Title,
			&i.Body,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Rank,
			&i.AnswerCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

